sp_CriarPedidoHistoricoInicial	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarPedidoHistoricoInicial`(\n\n    IN p_idPedido  INT,\n\n    IN p_idUsuario INT\n\n)\nBEGIN\n\n    INSERT INTO PedidoStatusHistorico (idPedido, statusPedido_id, idUsuario, dthAlteracao, observacao)\n\n    VALUES (p_idPedido, 1, p_idUsuario, NOW(), 'Pedido criado');\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
